        raise ValueError
    s = s.strip()
    if not s:
        raise ValueError
    if '-' in s:
        parts = s.split('-')
        if len(parts) != 2:
            raise ValueError
        a, b = parts
        if not a.isdigit() or not b.isdigit():
            raise ValueError
        a = int(a)
        b = int(b)
        if a >= b:
            raise ValueError
        return list(range(a, b + 1))
    else:
        if not s.isdigit():
            raise ValueError
        return [int(s)]
